"""Java - Intermediate and Advanced sections (units 9-16).

Runnable exercises stick to Java 11-15 features so they also compile on older sandbox runners;
newer features (records, sealed classes, pattern matching) are taught in the quiz exercises.
"""
from .dsl import code, fill, lesson, mcq, order, run, section, t, unit

MAIN = "public class Main {\n    public static void main(String[] args) {\n        \n    }\n}\n"
SCAN = "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner in = new Scanner(System.in);\n        \n    }\n}\n"


def prog(body: str, imports: str = "import java.util.*;\n\n", extra: str = "", before: str = "") -> str:
    inner = "\n".join(("        " + line) if line else "" for line in body.split("\n"))
    return f"{imports}{before}public class Main {{\n{extra}    public static void main(String[] args) {{\n{inner}\n    }}\n}}\n"


def scan(body: str, extra: str = "", before: str = "") -> str:
    return prog("Scanner in = new Scanner(System.in);\n" + body, extra=extra, before=before)


